1	import { useRef, useState, useEffect, useMemo } from 'react'
2	import { useVirtualizer } from '@tanstack/react-virtual'
3	import * as pageCache from '../../hooks/pageCache'
4	import { DEFAULT_WIDTH, DRAG_HANDLE_WIDTH, ITEM_PADDING, PAGE_ASPECT, LABEL_HEIGHT, HEADER_HEIGHT } from '../../constants'
5	import PageThumbnail from '../PageThumbnail'
6	import type { OutputFilesHandle } from './useOutputFiles'
7	import OutputFileHeader from './OutputFileHeader'
8	import type { PendingFocusHandle } from './usePendingFocus'
9	
10	const MIN_WIDTH = 120
11	const MAX_WIDTH = 480
12	const GAP_HEIGHT = 16
13	
14	type ListItem =
15	  | { type: 'header'; fileIndex: number; firstPage: number }
16	  | { type: 'page'; page: number }
17	
18	function buildItems(pageCount: number, splitPoints: Set<number>): ListItem[] {
19	  const result: ListItem[] = []
20	  let fileIndex = 0
21	  for (let page = 1; page <= pageCount; page++) {
22	    if (page === 1 || splitPoints.has(page - 1)) {
23	      result.push({ type: 'header', fileIndex: fileIndex++, firstPage: page })
24	    }
25	    result.push({ type: 'page', page })
26	  }
27	  return result
28	}
29	
30	interface Props {
31	  pdfPath: string
32	  pageCount: number
33	  selectedPage: number
34	  onSelectPage: (page: number) => void
35	  onToggleSplitPoint: (afterPage: number) => void
36	  outputFiles: OutputFilesHandle
37	  outputFolder: string | null
38	  focus: PendingFocusHandle
39	  rotations: Map<number, number>
40	  onRotate: (page: number) => void
41	  skipped: Set<number>
42	  onToggleSkip: (page: number) => void
43	}
44	
45	export default function SplitThumbnailPanel({
46	  pdfPath, pageCount, selectedPage, onSelectPage,
47	  onToggleSplitPoint,
48	  outputFiles,
49	  outputFolder,
50	  focus,
51	  rotations,
52	  onRotate,
53	  skipped,
54	  onToggleSkip,
55	}: Props) {
56	  const [panelWidth, setPanelWidth] = useState(DEFAULT_WIDTH)
57	  const [hoveredGap, setHoveredGap] = useState<number | null>(null)
58	  const [hoveredPage, setHoveredPage] = useState<number | null>(null)
59	
60	  const thumbWidth = panelWidth - ITEM_PADDING * 2
61	  const thumbHeight = Math.round(thumbWidth * PAGE_ASPECT)
62	  const pageItemHeight = thumbHeight + LABEL_HEIGHT + ITEM_PADDING + GAP_HEIGHT
63	
64	  const splitPoints = useMemo(() => outputFiles.getSplitPoints(), [outputFiles.all])
65	  const items = useMemo(() => buildItems(pageCount, splitPoints), [pageCount, splitPoints])
66	  // Ref so the scroll effect can read the current list without depending on it
67	  // (we don't want to re-scroll every time a split point is toggled).
68	  const itemsRef = useRef(items)
69	  itemsRef.current = items
70	
71	  const scrollRef = useRef<HTMLDivElement>(null)
72	
73	  const virtualizer = useVirtualizer({
74	    count: items.length,
75	    getScrollElement: () => scrollRef.current,
76	    estimateSize: (index) => items[index]?.type === 'header' ? HEADER_HEIGHT : pageItemHeight,
77	    overscan: 3,
78	  })
79	
80	  useEffect(() => {
81	    virtualizer.measure()
82	    // eslint-disable-next-line react-hooks/exhaustive-deps
83	  }, [items.length, pageItemHeight])
84	
85	  const virtualItems = virtualizer.getVirtualItems()
86	  pageCache.usePageCacheRender()
87	
88	  useEffect(() => {
89	    for (const vItem of virtualItems) {
90	      const item = items[vItem.index]
91	      if (item.type === 'page') pageCache.load(pdfPath, item.page, thumbWidth)
92	    }
93	  })
94	
95	  useEffect(() => {
96	    const index = itemsRef.current.findIndex(item => item.type === 'page' && item.page === selectedPage)
97	    if (index >= 0) virtualizer.scrollToIndex(index, { align: 'auto' })
98	    // eslint-disable-next-line react-hooks/exhaustive-deps
99	  }, [selectedPage])
100	
101	  useEffect(() => {
102	    const handler = (e: KeyboardEvent) => {
103	      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return
104	      if (e.key === 'ArrowLeft') {
105	        e.preventDefault()
106	        if (selectedPage > 1) onSelectPage(selectedPage - 1)
107	      } else if (e.key === 'ArrowRight') {
108	        e.preventDefault()
109	        if (selectedPage < pageCount) onSelectPage(selectedPage + 1)
110	      } else if (e.key === 'Delete' || e.key === 'Backspace') {
111	        e.preventDefault()
112	        onToggleSkip(selectedPage)
113	      }
114	    }
115	    window.addEventListener('keydown', handler)
116	    return () => window.removeEventListener('keydown', handler)
117	  }, [selectedPage, pageCount, onSelectPage, onToggleSkip])
118	
119	  const startDrag = (e: React.MouseEvent) => {
120	    const startX = e.clientX
121	    const startWidth = panelWidth
122	    const clamp = (w: number) => Math.max(MIN_WIDTH, Math.min(MAX_WIDTH, w))
123	    const onMove = (ev: MouseEvent) => setPanelWidth(clamp(startWidth + ev.clientX - startX))
124	    const onUp = (ev: MouseEvent) => {
125	      setPanelWidth(clamp(startWidth + ev.clientX - startX))
126	      document.removeEventListener('mousemove', onMove)
127	      document.removeEventListener('mouseup', onUp)
128	    }
129	    document.addEventListener('mousemove', onMove)
130	    document.addEventListener('mouseup', onUp)
131	    e.preventDefault()
132	  }
133	
134	  return (
135	    <div style={{ display: 'flex', height: '100%', flexShrink: 0 }}>
136	      <div style={{ display: 'flex', flexDirection: 'column', width: panelWidth, height: '100%' }}>
137	        <div
138	          ref={scrollRef}
139	          style={{
140	            flex: 1,
141	            minHeight: 0,
142	            overflowY: 'auto',
143	            overflowX: 'hidden',
144	            background: 'var(--mantine-color-gray-3)',
145	          }}
146	        >
147	          <div style={{ height: virtualizer.getTotalSize(), position: 'relative' }}>
148	            {virtualItems.map(vItem => {
149	              const item = items[vItem.index]
150	
151	              if (item.type === 'header') {
152	                return (
153	                  <div
154	                    key={vItem.key}
155	                    style={{ position: 'absolute', top: vItem.start, left: 0, width: '100%', height: vItem.size }}
156	                  >
157	                    <OutputFileHeader
158	                      filename={outputFiles.all.get(item.firstPage)?.name ?? ''}
159	                      onChange={(name) => outputFiles.setName(item.firstPage, name)}
160	                      firstPage={item.firstPage}
161	                      focus={focus}
162	                      folder={outputFiles.all.get(item.firstPage)?.folderOverride ?? outputFolder}
163	                      onPickFolder={() => outputFiles.pickFolderOverride(item.firstPage)}
164	                      isDuplicate={outputFiles.duplicateFirstPages.has(item.firstPage)}
165	                    />
166	                  </div>
167	                )
168	              }
169	
170	              const page = item.page
171	              const isSplit = splitPoints.has(page)
172	              const isLastPage = page === pageCount
173	
174	              return (
175	                <div
176	                  key={vItem.key}
177	                  style={{
178	                    position: 'absolute',
179	                    top: vItem.start,
180	                    left: 0,
181	                    width: '100%',
182	                    height: vItem.size,
183	                    boxSizing: 'border-box',
184	                  }}
185	                  onMouseEnter={() => setHoveredPage(page)}
186	                  onMouseLeave={() => setHoveredPage(null)}
187	                >
188	                  <PageThumbnail
189	                    src={pageCache.getSrc(pdfPath, page)}
190	                    pdfPath={pdfPath}
191	                    page={page}
192	                    thumbHeight={thumbHeight}
193	                    isSelected={page === selectedPage}
194	                    isSkipped={skipped.has(page)}
195	                    rotation={rotations.get(page) ?? 0}
196	                    isHovered={hoveredPage === page}
197	                    label={String(page)}
198	                    onClick={() => onSelectPage(page)}
199	                    onRotate={() => onRotate(page)}
200	                    onToggleSkip={() => onToggleSkip(page)}
201	                  />
202	                  {!isLastPage && (
203	                    <GapZone
204	                      isSplit={isSplit}
205	                      isHovered={hoveredGap === page}
206	                      onClick={(e) => { e.stopPropagation(); onToggleSplitPoint(page) }}
207	                      onMouseEnter={() => setHoveredGap(page)}
208	                      onMouseLeave={() => setHoveredGap(null)}
209	                    />
210	                  )}
211	                </div>
212	              )
213	            })}
214	          </div>
215	        </div>
216	      </div>
217	
218	      <div
219	        onMouseDown={startDrag}
220	        style={{
221	          width: DRAG_HANDLE_WIDTH,
222	          height: '100%',
223	          cursor: 'col-resize',
224	          flexShrink: 0,
225	          background: 'var(--mantine-color-gray-3)',
226	        }}
227	      />
228	    </div>
229	  )
230	}
231	
232	interface GapZoneProps {
233	  isSplit: boolean
234	  isHovered: boolean
235	  onClick: (e: React.MouseEvent) => void
236	  onMouseEnter: () => void
237	  onMouseLeave: () => void
238	}
239	
240	function GapZone({ isSplit, isHovered, onClick, onMouseEnter, onMouseLeave }: GapZoneProps) {
241	  const bg = isSplit
242	    ? 'var(--mantine-color-blue-0)'
243	    : isHovered
244	    ? 'var(--mantine-color-gray-2)'
245	    : undefined
246	
247	  return (
248	    <div
249	      onClick={onClick}
250	      onMouseEnter={onMouseEnter}
251	      onMouseLeave={onMouseLeave}
252	      style={{
253	        height: GAP_HEIGHT,
254	        background: bg,
255	        display: 'flex',
